import time
import json
import socket
import logging
import threading

import requests
from flask import Flask, jsonify
import bitcoinlib

logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s %(message)s')
log = logging.getLogger('bitcoin_service')

HTTP_TIMEOUT = 20

RPC_HOST = os.environ.get('BTC_RPC_HOST', '127.0.0.1')
RPC_PORT = int(os.environ.get('BTC_RPC_PORT', '8332'))
RPC_USER = os.environ.get('BTC_RPC_USER', '')
RPC_PASS = os.environ.get('BTC_RPC_PASS', '')
P2P_PORT = int(os.environ.get('BTC_P2P_PORT', '8333'))
PUBLIC_BLOCK_API = os.environ.get('BTC_PUBLIC_API', 'https://blockstream.info/api').rstrip('/')
LISTEN_PORT = int(os.environ.get('PORT', '5000'))


class NotConnected(Exception):
    pass


class NotFound(Exception):
    pass


class BitcoinCoreRPC:
    def __init__(self, host, port, user, pwd):
        self.url = 'http://%s:%s/' % (host, port)
        self.auth = (user, pwd) if user else None
        self._id = 0

    def call(self, method, params=None, timeout=HTTP_TIMEOUT):
        self._id += 1
        payload = {'jsonrpc': '1.0', 'id': self._id, 'method': method, 'params': params or []}
        try:
            r = requests.post(self.url, json=payload, auth=self.auth, timeout=timeout)
        except requests.RequestException as e:
            raise ConnectionError('RPC request failed: %s' % e) from e
        if r.status_code != 200:
            raise ConnectionError('RPC HTTP %s' % r.status_code)
        data = r.json()
        if data.get('error'):
            raise ValueError(data['error'])
        return data.get('result')

    def reachable(self):
        try:
            self.call('getblockchaininfo', timeout=8)
            return True
        except Exception:
            return False


