        self.timeout = timeout
        self.connected = False
        self.peer = None

    def connect(self):
        host = None
        for seed in self.SEEDS:
            try:
                infos = socket.getaddrinfo(seed, self.port, proto=socket.IPPROTO_TCP)
                if infos:
                    host = infos[0][4][0]
